function checkCollision(obs) {
  const p = G.player;
  /* 玩家始终在自己轨道上，障碍物也在特定轨道 */
  /* 轨道匹配 + 距离接近 + 高度状态匹配 */
  const laneMatch = Math.abs(obs.lane - p.lane) < 0.6;

  if (!laneMatch) return false;

  /* 低障碍：滑铲可通过，否则碰撞 */
  if (obs.type === OBS_LOW && p.state === STATE_SLIDE) return false;
  /* 中障碍：跳跃可通过，否则碰撞 */
  if (obs.type === OBS_MID && p.state === STATE_JUMP) return false;

  /* 高障碍在同轨道即碰撞 */
  return true;
}

