function drawObstacle(ctx, obs, sx, sy, scale) {
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);

  /* 直接绘制——绕过离屏精灵排查问题 */
  if (obs.type === OBS_LOW) {
    /* 低矮栏杆：亮黄+红条纹 */
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(-28, -12, 56, 10);
    ctx.fillStyle = '#ffdd00';
    ctx.fillRect(-26, -10, 52, 3);
    ctx.fillStyle = '#ff8800';
    ctx.fillRect(-28, -12, 56, 10);
    ctx.fillRect(-3, -16, 6, 22);
  } else if (obs.type === OBS_MID) {
    /* 中等信号箱：蓝+红灯 */
    ctx.fillStyle = '#2266cc';
    ctx.fillRect(-18, -30, 36, 50);
    ctx.fillStyle = '#ff0000';
    ctx.beginPath(); ctx.arc(0, -20, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#ffaa00';
    ctx.beginPath(); ctx.arc(0, -5, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#00cc00';
    ctx.beginPath(); ctx.arc(0, 10, 6, 0, Math.PI*2); ctx.fill();
  } else if (obs.type === OBS_HIGH) {
    /* 高大信号塔：红白柱 */
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(-14, -55, 28, 100);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-14, -40, 28, 12);
    ctx.fillRect(-14, -10, 28, 12);
    ctx.fillRect(-14, 20, 28, 12);
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(-20, -60, 40, 14);
  }

  ctx.restore();
}

